-- ============================================================================
-- ePeddlers - Development seed data
-- ----------------------------------------------------------------------------
-- WARNING: FOR DEVELOPMENT ONLY. Contains temporary credentials.
-- Replace all temporary passwords before any real/shared deployment.
-- No real personal information or real financial transactions are seeded.
-- Password hashes are generated by database/make_seed_users.php (bcrypt).
-- ============================================================================

SET NAMES utf8mb4;

-- ---------------------------------------------------------------------------
-- Roles
-- ---------------------------------------------------------------------------
INSERT INTO roles (code, name, category, description) VALUES
    ('admin',             'Admin / Supervisor', 'admin',          'Supervises the entire system'),
    ('treasury',          'Treasury Officer',   'treasury',       'Payment verification and collection records'),
    ('inspection_officer','Inspection Officer', 'administrative', 'Conducts general inspections (mobile)'),
    ('sanitary_officer',  'Sanitary Officer',   'administrative', 'Conducts sanitary reviews (mobile)')
ON DUPLICATE KEY UPDATE name = VALUES(name);

-- ---------------------------------------------------------------------------
-- Permissions
-- ---------------------------------------------------------------------------
INSERT INTO permissions (code, description) VALUES
    ('users.manage',            'Create/edit/activate users and reset passwords'),
    ('users.view',              'View user accounts'),
    ('applications.view',       'View applications'),
    ('applications.review',     'Initial review / return for correction'),
    ('applications.approve',    'Final permit approval and issuance'),
    ('applications.reject',     'Reject applications'),
    ('inspections.conduct',     'Record general inspection results'),
    ('sanitary.conduct',        'Record sanitary review results'),
    ('treasury.verify',         'Verify payments'),
    ('treasury.collect',        'Record arkabala/tax collections'),
    ('treasury.reports',        'Generate treasury reports'),
    ('collections.record',      'Record collections (mobile, authorized)'),
    ('qr.resolve',              'Resolve peddler QR codes'),
    ('violations.record',       'Record violations and sanctions'),
    ('violations.view',         'View violations'),
    ('reports.view',            'View reports'),
    ('activity.view',           'View activity logs'),
    ('settings.manage',         'Manage system settings and fee configuration')
ON DUPLICATE KEY UPDATE description = VALUES(description);

-- ---------------------------------------------------------------------------
-- Role -> Permission matrix
-- ---------------------------------------------------------------------------
-- Admin: everything
INSERT IGNORE INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r JOIN permissions p
WHERE r.code = 'admin';

-- Treasury
INSERT IGNORE INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r JOIN permissions p
WHERE r.code = 'treasury'
  AND p.code IN ('applications.view','treasury.verify','treasury.collect',
                 'treasury.reports','reports.view','qr.resolve');

-- Inspection Officer
INSERT IGNORE INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r JOIN permissions p
WHERE r.code = 'inspection_officer'
  AND p.code IN ('applications.view','inspections.conduct','qr.resolve',
                 'violations.record','violations.view','collections.record');

-- Sanitary Officer
INSERT IGNORE INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id FROM roles r JOIN permissions p
WHERE r.code = 'sanitary_officer'
  AND p.code IN ('applications.view','sanitary.conduct','qr.resolve','violations.view');

-- ---------------------------------------------------------------------------
-- Fee categories (configurable - amounts are PLACEHOLDERS, not official policy)
-- ---------------------------------------------------------------------------
INSERT INTO fee_categories (code, name, kind, description) VALUES
    ('permit_fee',     'Peddler Permit Fee',   'permit',   'PLACEHOLDER - set per approved city policy'),
    ('arkabala_daily', 'Arkabala Daily Fee',   'arkabala', 'PLACEHOLDER - set per approved city policy'),
    ('penalty_late',   'Late Renewal Penalty', 'penalty',  'PLACEHOLDER - set per approved city policy')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO fee_schedules (fee_category_id, amount, effective_from)
SELECT id, 0.00, CURDATE() FROM fee_categories
WHERE code IN ('permit_fee','arkabala_daily','penalty_late');

-- ---------------------------------------------------------------------------
-- Violation categories (placeholders - configurable)
-- ---------------------------------------------------------------------------
INSERT INTO violation_categories (code, name, description) VALUES
    ('no_permit',      'Vending without valid permit', 'PLACEHOLDER category'),
    ('wrong_area',     'Vending outside authorized area', 'PLACEHOLDER category'),
    ('sanitation',     'Sanitation non-compliance', 'PLACEHOLDER category')
ON DUPLICATE KEY UPDATE name = VALUES(name);

-- ---------------------------------------------------------------------------
-- System settings
-- ---------------------------------------------------------------------------
INSERT INTO system_settings (setting_key, setting_value, value_type, description) VALUES
    ('app.timezone',            'Asia/Manila', 'string', 'La Carlota City local timezone'),
    ('permit.code_prefix',      'EP',          'string', 'Permit code prefix'),
    ('permit.validity_days',    '365',         'int',    'Default permit validity in days'),
    ('treasury.report_day',     '6',           'int',    'Weekly report day (0=Sun..6=Sat); Saturday=6'),
    ('polling.interval_ms',     '3000',        'int',    'Dashboard background polling interval'),
    ('uploads.max_size_bytes',  '5242880',     'int',    'Max upload size (5MB)'),
    ('uploads.allowed_mimes',   'image/jpeg,image/png,application/pdf', 'string', 'Allowed document MIME types'),
    ('mapping.enabled',         '0',           'bool',   'Vendor mapping ON STANDBY'),
    ('content.mission',         'DRAFT - pending official approval by La Carlota City.', 'string', 'Public mission text'),
    ('content.vision',          'DRAFT - pending official approval by La Carlota City.', 'string', 'Public vision text')
ON DUPLICATE KEY UPDATE description = VALUES(description);

